-- CreditScope sample data: 30 users/applicants/applications with varied risk profiles.
-- Run in MySQL Workbench against the `creditscope` schema AFTER the app has created the tables.
-- Seed users get a placeholder password hash, so they cannot log in; use your own registered user for API calls.
USE creditscope;

-- Re-runnable: removes ONLY previously seeded rows (users with @seed.creditscope.test emails); your own data is untouched
SET SQL_SAFE_UPDATES = 0;
DELETE FROM score_factor WHERE application_id IN (SELECT la.id FROM loan_application la WHERE la.applicant_id IN (SELECT a.id FROM applicant a JOIN `user` u ON u.id=a.user_id WHERE u.email LIKE '%@seed.creditscope.test'));
DELETE FROM credit_score_result WHERE application_id IN (SELECT la.id FROM loan_application la WHERE la.applicant_id IN (SELECT a.id FROM applicant a JOIN `user` u ON u.id=a.user_id WHERE u.email LIKE '%@seed.creditscope.test'));
DELETE FROM repayment_history WHERE applicant_id IN (SELECT a.id FROM applicant a JOIN `user` u ON u.id=a.user_id WHERE u.email LIKE '%@seed.creditscope.test');
DELETE FROM existing_loan WHERE applicant_id IN (SELECT a.id FROM applicant a JOIN `user` u ON u.id=a.user_id WHERE u.email LIKE '%@seed.creditscope.test');
DELETE FROM loan_application WHERE applicant_id IN (SELECT a.id FROM applicant a JOIN `user` u ON u.id=a.user_id WHERE u.email LIKE '%@seed.creditscope.test');
DELETE a FROM applicant a JOIN `user` u ON u.id=a.user_id WHERE u.email LIKE '%@seed.creditscope.test';
DELETE FROM `user` WHERE email LIKE '%@seed.creditscope.test';
SET SQL_SAFE_UPDATES = 1;


-- Applicants link to users by email, so existing ids don't matter




SELECT 'users' t,COUNT(*) FROM `user` UNION ALL SELECT 'applicants',COUNT(*) FROM applicant UNION ALL SELECT 'existing_loans',COUNT(*) FROM existing_loan UNION ALL SELECT 'repayments',COUNT(*) FROM repayment_history UNION ALL SELECT 'applications',COUNT(*) FROM loan_application;